// Garder l'écran allumé (téléphones, tablette de jeu, télécommande).
// 1) l'API officielle (Screen Wake Lock), reprise à chaque retour sur la page ;
// 2) en secours (iPhone en mode « app », anciens navigateurs) : une minuscule
//    vidéo muette jouée en boucle, qui empêche la mise en veille.
// Les deux ne démarrent qu'après un appui sur l'écran (règle des navigateurs).

const VIDEO = 'data:video/mp4;base64,';

let lock = null;
let video = null;

async function requestLock() {
  if (!('wakeLock' in navigator) || lock) return !!lock;
  try {
    lock = await navigator.wakeLock.request('screen');
    lock.addEventListener('release', () => (lock = null));
    return true;
  } catch {
    return false;
  }
}

function playVideo() {
  if (!video) {
    video = document.createElement('video');
    video.setAttribute('playsinline', '');
    video.setAttribute('muted', '');
    video.muted = true;
    video.loop = true;
    video.src = VIDEO;
    Object.assign(video.style, { position: 'fixed', width: '1px', height: '1px', opacity: '0.01', pointerEvents: 'none', bottom: '0', left: '0' });
    document.body.appendChild(video);
  }
  if (video.paused) video.play().catch(() => {});
}

async function keepAwake() {
  const ok = await requestLock();
  if (!ok) playVideo();
}

export function setupKeepAwake() {
  // à chaque appui (le premier débloque tout) et à chaque retour sur la page
  document.addEventListener('pointerdown', keepAwake, { capture: true, passive: true });
  document.addEventListener('visibilitychange', () => {
    if (document.visibilityState === 'visible') {
      lock = null;
      keepAwake();
    }
  });
}
